# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: agents/manager.py

import os
from openai import OpenAI
from dotenv import load_dotenv
from agents import qualitative, quantitative
from validation.validator import validate_qualitative, validate_quantitative
from tokenomics.logger import log

load_dotenv()

client = OpenAI(
    api_key=os.getenv("GEMINI_API_KEY"),
    base_url="https://generativelanguage.googleapis.com/v1beta/openai/"
)

_HISTORY: list[dict] = []
_MAX_TURNS = 5


def _history_context() -> str:
    if not _HISTORY:
        return ""
    lines = ["Previous conversation (most recent last):"]
    for turn in _HISTORY:
        lines.append(f"User: {turn['query']}\nAssistant: {turn['answer']}")
    return "\n\n".join(lines) + "\n\n"


def _classifier_context() -> str:
    # Routing only needs prior topics, so send questions only, not answers.
    if not _HISTORY:
        return ""
    qs = "\n".join(f"- {t['query']}" for t in _HISTORY)
    return f"Earlier questions this session:\n{qs}\n\n"


def _remember(query: str, answer: str) -> None:
    _HISTORY.append({"query": query, "answer": answer})
    del _HISTORY[:-_MAX_TURNS]


def classify(query: str) -> str:
    context = _classifier_context()
    response = client.chat.completions.create(
        model="gemini-3.5-flash-lite",
        max_tokens=10,
        messages=[{
            "role": "user",
            "content": f"""{context}Classify this query as exactly one of: qualitative, quantitative, both.

qualitative = questions about policies, processes, procedures, explanations, documentation
quantitative = questions about numbers, metrics, trends, comparisons, SQL-queryable data
both = questions that need both document search and data analysis

If the query is a short follow-up to a previous data/metrics question
(e.g. "what about North?", "and for 2023?"), classify it the same as that
prior question — do not add qualitative unless the follow-up clearly asks
about policies or documents.

Query: {query}

Reply with one word only: qualitative, quantitative, or both."""
        }]
    )
    route = response.choices[0].message.content.strip().lower()
    log(query, "manager-classifier", response.usage.prompt_tokens, response.usage.completion_tokens)
    return route if route in ["qualitative", "quantitative", "both"] else "qualitative"


def run(query: str):
    print(f"\nQuery: {query}")
    route = classify(query)
    print(f"Route: {route}")

    context = _history_context()
    qual_result = None
    quant_result = None
    answer_parts = []

    if route in ["qualitative", "both"]:
        qual_result = qualitative.run(query, history_context=context)
        validation = validate_qualitative(qual_result["answer"], qual_result["chunks"])
        log(query, "qualitative", qual_result["input_tokens"], qual_result["output_tokens"])
        if validation["flag"]:
            print(f"\n⚠️  VALIDATION WARNING: {validation['warning']}")
        print(f"\n[Qualitative]\n{qual_result['answer']}")
        answer_parts.append(qual_result["answer"])

    if route in ["quantitative", "both"]:
        quant_result = quantitative.run(query, history_context=context)
        validation = validate_quantitative(
            quant_result["answer"],
            quant_result["sql"],
            quant_result["validation"]
        )
        log(query, "quantitative", quant_result["input_tokens"], quant_result["output_tokens"])
        if validation["flag"]:
            print(f"\n⚠️  VALIDATION WARNING: {validation['warning']}")
        print(f"\n[Quantitative]\n{quant_result['answer']}")
        print(f"SQL used: {quant_result['sql']}")
        answer_parts.append(quant_result["answer"])

    _remember(query, "\n\n".join(answer_parts))
